 49→const DEFAULT_SEGMENTATION_THRESHOLD = 100;
 50→
 51→/**
 52→ * Identify message parts that are greater than the token threshold
 53→ */
 54→function identifyLargeParts(
 55→  conversation: Conversation,
 56→  conversationId?: string,
 57→  threshold: number = DEFAULT_SEGMENTATION_THRESHOLD,
 58→): Array<{
 59→  messageIndex: number;
 60→  partIndex: number;
 61→  part: Message["parts"][number];
 62→}> {
 63→  log(conversationId, `Using threshold: ${threshold} tokens`);
 64→
 65→  const largeParts: Array<{
 66→    messageIndex: number;
 67→    partIndex: number;
 68→    part: Message["parts"][number];
 69→  }> = [];
 70→
 71→  conversation.messages.forEach((message, messageIndex) => {
 72→    message.parts.forEach((part, partIndex) => {
 73→      const tokenCount = ("token_count" in part && part.token_count) || 0;
 74→      if (tokenCount > threshold) {
 75→        log(
 76→          conversationId,
 77→          `Found large part: message ${messageIndex}, part ${partIndex}, tokens: ${tokenCount}`,
 78→        );
 79→        largeParts.push({ messageIndex, partIndex, part });
 80→      }
 81→    });
 82→  });
 83→
 84→  log(
 85→    conversationId,
 86→    `Found ${largeParts.length} large parts (>${threshold} tokens)`,
 87→  );
 88→  return largeParts;
 89→}
