 91→/**
 92→ * Use AI to split a text part into semantic segments
 93→ */
 94→async function segmentTextWithAI(
 95→  text: string,
 96→  config: AIConfig,
 97→  customPrompt?: string,
 98→  conversationId?: string,
 99→): Promise<string[]> {
100→  const openai = createOpenAI({
101→    apiKey: config.apiKey,
102→  });
103→
104→  log(
105→    conversationId,
106→    `Calling AI to segment text (${text.length} chars, model: ${config.model})${customPrompt ? " with custom prompt" : ""}`,
107→  );
108→
109→  const prompt = getPrompt("segmentation", { text, customPrompt });
110→
111→  try {
112→    const result = await generateText({
113→      model: openai(config.model),
114→      prompt,
115→    });
116→
117→    log(conversationId, `AI response: ${result.text.substring(0, 200)}...`);
118→
119→    // Parse the JSON response
120→    const jsonMatch = result.text.match(/\[.*\]/s);
121→    if (!jsonMatch) {
122→      log(conversationId, "No JSON array found in response");
123→      return [];
124→    }
125→
126→    const substrings = JSON.parse(jsonMatch[0]);
127→
128→    if (!Array.isArray(substrings)) {
129→      log(conversationId, "Parsed result is not an array");
130→      return [];
131→    }
132→
133→    log(
134→      conversationId,
135→      `Parsed ${substrings.length} split patterns`,
136→      substrings,
137→    );
138→    return substrings;
139→  } catch (error) {
140→    logError(conversationId, "Error calling AI", error);
141→    return [];
142→  }
143→}
