145→/**
146→ * Preprocess regex patterns to make them work correctly with split()
147→ * Removes ^ and $ anchors from inside lookaheads since they don't work correctly
148→ * when used with String.split()
149→ */
150→function preprocessPattern(pattern: string): string {
151→  // Remove ^ anchor (start of line) from inside lookaheads
152→  // (?=^...) -> (?=...)
153→  let processed = pattern.replace(/\(\?=\^/g, "(?=");
154→
155→  // Remove $ anchor (end of line) from inside lookaheads
156→  // ...\\s*$) -> ...\\s*)
157→  processed = processed.replace(/\$\)/g, ")");
158→
159→  // Also handle \s*$ patterns
160→  processed = processed.replace(/\\s\*\$/g, "\\s*");
161→
162→  return processed;
163→}
164→
165→/**
166→ * Split a text using an array of regex patterns or substrings
167→ * Returns the parts of the text separated by the patterns
168→ * Supports positive lookahead patterns like (?=<tag>)
169→ */
170→function splitTextBySubstrings(
171→  text: string,
172→  substrings: string[],
173→  conversationId?: string,
174→): string[] {
175→  if (substrings.length === 0) {
176→    return [text];
177→  }
178→
179→  try {
180→    // Preprocess patterns to remove anchors that don't work with split()
181→    const processedPatterns = substrings.map(preprocessPattern);
182→
183→    // Combine all patterns into a single regex with alternation
184→    const combinedPattern = processedPatterns.join("|");
185→    const regex = new RegExp(combinedPattern);
186→
187→    // Split using the combined regex
188→    const parts = text.split(regex);
189→
190→    // Filter out empty strings and trim whitespace
191→    return parts.map((part) => part.trim()).filter((part) => part.length > 0);
192→  } catch (error) {
193→    logError(conversationId, "Regex error", error);
194→    // Fallback: return the original text if regex fails
195→    return [text];
196→  }
197→}
198→
199→/**
200→ * Generate a child ID based on parent ID and index
201→ */
202→function generateChildId(parentId: string, index: number): string {
203→  return `${parentId}.${index}`;
204→}
205→
206→type SegmentResult =
207→  | { success: true; parts: Message["parts"] }
208→  | { success: false; skipped: true }
209→  | { success: false; error: true };
210→
211→/**
212→ * Segment a single large message part
213→ */
214→async function segmentMessagePart(
215→  part: Message["parts"][number],
216→  config: AIConfig,
217→  customPrompt?: string,
218→  conversationId?: string,
219→): Promise<SegmentResult> {
220→  // Get text content from different part types
221→  // Only segment text and reasoning parts - skip tool results as they're usually structured output
222→  let text: string;
223→
224→  if (part.type === "text" || part.type === "reasoning") {
225→    text = part.text;
226→  } else {
227→    log(conversationId, `Skipping part ${part.id}, type: ${part.type}`);
228→    return { success: false, skipped: true };
229→  }
230→
231→  log(
232→    conversationId,
233→    `Processing part ${part.id}, type: ${part.type}, text length: ${text.length}`,
234→  );
235→  const substrings = await segmentTextWithAI(
236→    text,
237→    config,
238→    customPrompt,
239→    conversationId,
240→  );
241→
242→  if (substrings.length === 0) {
243→    log(conversationId, `No substrings returned for part ${part.id}`);
244→    return { success: false, error: true };
245→  }
246→
247→  const segments = splitTextBySubstrings(text, substrings, conversationId);
248→
249→  if (segments.length <= 1) {
250→    log(
251→      conversationId,
252→      `Split resulted in ${segments.length} segment(s), not segmenting`,
253→    );
254→    return { success: false, skipped: true };
255→  }
256→
257→  log(
258→    conversationId,
259→    `Successfully split part ${part.id} into ${segments.length} segments`,
260→  );
261→
262→  // Create new parts with child IDs
263→  const newParts = segments.map((segment, index) => {
264→    const basePart = {
265→      ...part,
266→      id: generateChildId(part.id, index + 1),
267→      token_count: undefined, // Will be recalculated
268→    };
269→
270→    // Only text and reasoning parts are segmented
271→    return {
272→      ...basePart,
273→      text: segment,
274→    };
275→  });
276→
277→  return { success: true, parts: newParts as Message["parts"] };
278→}
