280→/**
281→ * Process conversation segmentation with parallel processing of large parts
282→ * Returns a new conversation with segmented parts and error info
283→ */
284→export { DEFAULT_SEGMENTATION_THRESHOLD };
285→
286→export async function segmentConversation(
287→  conversation: Conversation,
288→  onProgress?: (processed: number, total: number) => void,
289→  customPrompt?: string,
290→  conversationId?: string,
291→  segmentationThreshold?: number,
292→): Promise<{ conversation: Conversation; error?: string }> {
293→  log(conversationId, "Starting segmentation process");
294→
295→  const config = getAIConfig("Segmentation");
296→
297→  if (!config) {
298→    return { conversation, error: "Segmentation: No API key configured" };
299→  }
300→
301→  const largeParts = identifyLargeParts(conversation, conversationId, segmentationThreshold);
302→
303→  if (largeParts.length === 0) {
304→    log(
305→      conversationId,
306→      "No large parts to segment, returning original conversation",
307→    );
308→    return { conversation };
309→  }
310→
311→  // Process all large parts in parallel
312→  const segmentationPromises = largeParts.map(
313→    async ({ messageIndex, partIndex, part }) => {
314→      const result = await segmentMessagePart(
315→        part,
316→        config,
317→        customPrompt,
318→        conversationId,
319→      );
320→      return { messageIndex, partIndex, result };
321→    },
322→  );
323→
324→  // Track progress and collect actual failures (not skips)
325→  let completed = 0;
326→  let errorCount = 0;
327→  let processedCount = 0;
328→  const results = await Promise.all(
329→    segmentationPromises.map(async (promise) => {
330→      const { messageIndex, partIndex, result } = await promise;
331→      if (!result.success && "error" in result && result.error) {
332→        errorCount++;
333→      }
334→      if (result.success) {
335→        processedCount++;
336→      }
337→      completed++;
338→      onProgress?.(completed, largeParts.length);
339→      return { messageIndex, partIndex, result };
340→    }),
341→  );
342→
343→  // Build a map of replacements
344→  const replacements = new Map<
345→    string,
346→    Array<{ partIndex: number; segments: Message["parts"] }>
347→  >();
348→
349→  for (const { messageIndex, partIndex, result } of results) {
350→    if (!result.success) continue;
351→
352→    const key = messageIndex.toString();
353→    if (!replacements.has(key)) {
354→      replacements.set(key, []);
355→    }
356→    replacements.get(key)!.push({
357→      partIndex,
358→      segments: result.parts,
359→    });
360→  }
361→
362→  // Apply replacements to create a new conversation
363→  const newMessages = conversation.messages.map((message, messageIndex) => {
364→    const messageReplacements = replacements.get(messageIndex.toString());
365→
366→    if (!messageReplacements || messageReplacements.length === 0) {
367→      return message;
368→    }
369→
370→    // Sort replacements by partIndex in descending order
371→    // This ensures we replace from the end first, keeping indices valid
372→    messageReplacements.sort((a, b) => b.partIndex - a.partIndex);
373→
374→    const newParts = [...message.parts];
375→
376→    for (const { partIndex, segments } of messageReplacements) {
377→      // Replace the part at partIndex with the segments
378→      newParts.splice(partIndex, 1, ...segments);
379→    }
380→
381→    // Create a new message with the updated parts
382→    // We need to maintain the correct type based on role
383→    if (message.role === "system") {
384→      return {
385→        ...message,
386→        parts: newParts as typeof message.parts,
387→      };
388→    } else if (message.role === "user") {
389→      return {
390→        ...message,
391→        parts: newParts as typeof message.parts,
392→      };
393→    } else if (message.role === "assistant") {
394→      return {
395→        ...message,
396→        parts: newParts as typeof message.parts,
397→      };
398→    } else {
399→      // tool message
400→      return {
401→        ...message,
402→        parts: newParts as typeof message.parts,
403→      };
404→    }
405→  });
406→
407→  const newConversation = {
408→    messages: newMessages as Message[],
409→  };
410→
411→  // Return with error info if any segmentations had actual errors (not skips)
412→  if (errorCount > 0) {
413→    return {
414→      conversation: newConversation,
415→      error: `Segmentation: Failed to segment ${errorCount} of ${processedCount} parts (API error)`,
416→    };
417→  }
418→
419→  return { conversation: newConversation };
420→}
