 72→/**
 73→ * Configuration for AI model used in componentisation
 74→ * Re-exported for backwards compatibility
 75→ */
 76→export type ComponentisationConfig = AIConfig;
 77→
 78→/**
 79→ * Get componentisation configuration from environment variables
 80→ */
 81→export const getComponentisationConfig = () => getAIConfig("Componentisation");
 82→
 83→/**
 84→ * Identify components in a conversation using AI
 85→ * Returns a list of component names
 86→ */
 87→export async function identifyComponents(
 88→  conversation: Conversation,
 89→  config: ComponentisationConfig,
 90→  customPrompt?: string,
 91→  conversationId?: string,
 92→): Promise<string[]> {
 93→  const openai = createOpenAI({
 94→    apiKey: config.apiKey,
 95→  });
 96→
 97→  // Strip binary data to reduce token count
 98→  const strippedConversation = stripLargeContent(conversation);
 99→  const conversationJson = JSON.stringify(strippedConversation, null, 2);
100→
101→  log(
102→    conversationId,
103→    `Calling AI to identify components (model: ${config.model})${customPrompt ? " with custom prompt" : ""}`,
104→  );
105→
106→  const prompt = getPrompt("component-identification", {
107→    conversationJson,
108→    customPrompt,
109→  });
110→
111→  try {
112→    const result = await generateText({
113→      model: openai(config.model),
114→      prompt,
115→    });
116→
117→    log(
118→      conversationId,
119→      `AI response for components: ${result.text.substring(0, 200)}...`,
120→    );
121→
122→    // Parse the JSON response
123→    const jsonMatch = result.text.match(/\[.*\]/s);
124→    if (!jsonMatch) {
125→      log(conversationId, "No JSON array found in response");
126→      return [];
127→    }
128→
129→    const components = JSON.parse(jsonMatch[0]);
130→
131→    if (!Array.isArray(components)) {
132→      log(conversationId, "Parsed result is not an array");
133→      return [];
134→    }
135→
136→    log(
137→      conversationId,
138→      `Identified ${components.length} components`,
139→      components,
140→    );
141→    return components;
142→  } catch (error) {
143→    logError(conversationId, "Error calling AI for components", error);
144→    return [];
145→  }
146→}
