148→/**
149→ * Extract all parts from a conversation with their context
150→ */
151→interface PartWithContext {
152→  partId: string;
153→  messageIndex: number;
154→  role: string;
155→  partType: string;
156→  content: unknown;
157→}
158→
159→function extractPartsWithContext(
160→  conversation: Conversation,
161→): PartWithContext[] {
162→  const parts: PartWithContext[] = [];
163→
164→  conversation.messages.forEach((message, messageIndex) => {
165→    message.parts.forEach((part) => {
166→      let content: unknown;
167→
168→      // Extract relevant content based on part type
169→      if (part.type === "text" || part.type === "reasoning") {
170→        content = part.text;
171→      } else if (part.type === "tool-call") {
172→        content = { toolName: part.toolName, input: part.input };
173→      } else if (part.type === "tool-result") {
174→        content = { toolName: part.toolName, output: part.output };
175→      } else if (part.type === "image") {
176→        content = "[IMAGE]";
177→      } else if (part.type === "file") {
178→        content = "[FILE]";
179→      }
180→
181→      parts.push({
182→        partId: part.id,
183→        messageIndex,
184→        role: message.role,
185→        partType: part.type,
186→        content,
187→      });
188→    });
189→  });
190→
191→  return parts;
192→}
