468→/**
469→ * Componentise a conversation: identify components and map them to message IDs
470→ * Returns the list of components, the mapping, timeline data, and error info
471→ */
472→export async function componentiseConversation(
473→  conversation: Conversation,
474→  onProgress?: (step: "identifying" | "mapping") => void,
475→  customPrompt?: string,
476→  customComponents?: string[],
477→  conversationId?: string,
478→): Promise<{
479→  components: string[];
480→  mapping: Record<string, string>;
481→  timeline: ComponentTimelineSnapshot[];
482→  error?: string;
483→}> {
484→  log(conversationId, "Starting componentisation process");
485→
486→  const config = getComponentisationConfig();
487→
488→  if (!config) {
489→    log(conversationId, "No config, skipping componentisation");
490→    return {
491→      components: [],
492→      mapping: {},
493→      timeline: [],
494→      error: "Componentisation: No API key configured",
495→    };
496→  }
497→
498→  // Step 1: Identify components (or use custom components if provided)
499→  let components: string[];
500→  if (customComponents && customComponents.length > 0) {
501→    // Normalize custom components - strip leading "- " prefix
502→    components = customComponents.map((c) => c.replace(/^-\s*/, ""));
503→    log(
504→      conversationId,
505→      `Using ${components.length} custom components (normalized)`,
506→    );
507→  } else {
508→    onProgress?.("identifying");
509→    components = await identifyComponents(
510→      conversation,
511→      config,
512→      customPrompt,
513→      conversationId,
514→    );
515→
516→    if (components.length === 0) {
517→      log(conversationId, "No components identified");
518→      return {
519→        components: [],
520→        mapping: {},
521→        timeline: [],
522→        error: "Componentisation: Failed to identify components (API error)",
523→      };
524→    }
525→  }
526→
527→  // Step 2: Map components to IDs
528→  onProgress?.("mapping");
529→  const componentDescriptions = customPrompt || getDefaultComponentIdentificationPrompt();
530→  const mapping = await mapComponentsToIds(
531→    conversation,
532→    components,
533→    config,
534→    componentDescriptions,
535→    conversationId,
536→  );
537→
538→  // Check if there are unmapped parts and add "other" component if needed
539→  const totalParts = conversation.messages.reduce(
540→    (sum, msg) => sum + msg.parts.length,
541→    0,
542→  );
543→  const mappedParts = Object.keys(mapping).length;
544→  const finalComponents =
545→    mappedParts < totalParts && !components.includes("other")
546→      ? [...components, "other"]
547→      : components;
548→
549→  // Step 3: Build timeline
550→  const timeline = buildComponentTimeline(
551→    conversation,
552→    mapping,
553→    conversationId,
554→  );
555→
556→  log(conversationId, "Completed componentisation");
557→  return { components: finalComponents, mapping, timeline };
558→}
