102→/**
103→ * Convert hex color to RGB components
104→ */
105→export function hexToRgb(hex: string): { r: number; g: number; b: number } {
106→  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
107→  if (!result) {
108→    return { r: 156, g: 163, b: 175 }; // gray-400 fallback
109→  }
110→  return {
111→    r: parseInt(result[1]!, 16),
112→    g: parseInt(result[2]!, 16),
113→    b: parseInt(result[3]!, 16),
114→  };
115→}
116→
117→/**
118→ * Convert RGB to hex color
119→ */
120→export function rgbToHex(r: number, g: number, b: number): string {
121→  const toHex = (n: number) => {
122→    const clamped = Math.max(0, Math.min(255, Math.round(n)));
123→    return clamped.toString(16).padStart(2, "0");
124→  };
125→  return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
126→}
