299→/**
300→ * Calculate conversation stats for the summary prompt
301→ */
302→function calculateConversationStats(conversation: {
303→  messages: Array<{ role: string; timestamp?: string }>;
304→}): ConversationStats {
305→  const messages = conversation.messages;
306→  const messageCount = messages.length;
307→  const turnCount = messages.filter((m) => m.role === "user").length;
308→
309→  let durationMs: number | undefined;
310→  let firstTimestamp: Date | undefined;
311→  let lastTimestamp: Date | undefined;
312→
313→  for (const message of messages) {
314→    if (message.timestamp) {
315→      const ts = new Date(message.timestamp);
316→      if (!isNaN(ts.getTime())) {
317→        if (!firstTimestamp || ts < firstTimestamp) firstTimestamp = ts;
318→        if (!lastTimestamp || ts > lastTimestamp) lastTimestamp = ts;
319→      }
320→    }
321→  }
322→
323→  if (firstTimestamp && lastTimestamp) {
324→    durationMs = lastTimestamp.getTime() - firstTimestamp.getTime();
325→  }
326→
327→  return { messageCount, turnCount, durationMs };
328→}
