336→): Record<string, string> {
337→  const mapping: Record<string, string> = {};
338→  for (const message of conversation.messages) {
339→    for (const part of message.parts) {
340→      // Parts from Context Viewer export have component embedded
341→      if ("component" in part && part.component) {
342→        mapping[part.id] = part.component as string;
343→      }
344→    }
345→  }
346→  return mapping;
