 22→/**
 23→ * Format duration in a human-readable format
 24→ */
 25→function formatDuration(ms: number): string {
 26→  const seconds = Math.floor(ms / 1000);
 27→  const minutes = Math.floor(seconds / 60);
 28→  const hours = Math.floor(minutes / 60);
 29→
 30→  if (hours > 0) {
 31→    const remainingMinutes = minutes % 60;
 32→    return `${hours}h ${remainingMinutes}m`;
 33→  } else if (minutes > 0) {
 34→    const remainingSeconds = seconds % 60;
 35→    return `${minutes}m ${remainingSeconds}s`;
 36→  } else {
 37→    return `${seconds}s`;
 38→  }
 39→}
 40→
 41→/**
 42→ * Extract the category (prefix before first dot) from a component name
 43→ */
 44→function getCategory(component: string): string {
 45→  const dotIndex = component.indexOf(".");
 46→  return dotIndex > 0 ? component.substring(0, dotIndex) : component;
 47→}
 48→
 49→/**
 50→ * Sort components by category - groups components by their prefix,
 51→ * sorts categories by total tokens, then sorts within each category by tokens
 52→ */
 53→function sortByCategory(
 54→  componentTokens: Record<string, number>,
 55→  direction: SortDirection
 56→): Array<{ component: string; tokens: number; percentage: number; category: string }> {
 57→  // Calculate total tokens
 58→  const totalTokens = Object.values(componentTokens).reduce((sum, t) => sum + t, 0);
 59→
 60→  // Build component data with category info
 61→  const componentData = Object.entries(componentTokens).map(([component, tokens]) => ({
 62→    component,
 63→    tokens,
 64→    percentage: totalTokens > 0 ? (tokens / totalTokens) * 100 : 0,
 65→    category: getCategory(component),
 66→  }));
 67→
 68→  // Calculate category totals
 69→  const categoryTotals: Record<string, number> = {};
 70→  for (const { category, tokens } of componentData) {
 71→    categoryTotals[category] = (categoryTotals[category] || 0) + tokens;
 72→  }
 73→
 74→  // Sort: first by category total, then by individual tokens within category
 75→  const dir = direction === "asc" ? 1 : -1;
 76→  return componentData.sort((a, b) => {
 77→    const categoryCompare = ((categoryTotals[b.category] || 0) - (categoryTotals[a.category] || 0)) * dir;
 78→    if (categoryCompare !== 0) return categoryCompare;
 79→    // Within same category, sort by tokens in same direction
 80→    return (b.tokens - a.tokens) * dir;
 81→  });
 82→}
