411→ */
412→class WorkflowRunner {
413→  constructor(
414→    private setState: (id: string, update: Partial<WorkflowState>) => void,
415→  ) {}
416→
417→  /**
418→   * Run an activity with timing tracking and logging
419→   */
420→  async runActivity<T>(
421→    ctx: Readonly<WorkflowState>,
422→    activity: Activity<T>,
423→    step?: ProcessingStep,
424→  ): Promise<{ result: T; timing: number }> {
425→    const start = Date.now();
426→    const result = await activity(ctx);
427→    const timing = Math.round((Date.now() - start) / 1000);
428→
429→    // Mark step end in the logging system if step is provided
430→    if (step) {
431→      markStepEnd(ctx.id, step as ProcessingPhase);
432→    }
433→
434→    return { result, timing };
435→  }
436→
437→  /**
438→   * Update state to mark a step as starting
439→   */
440→  startStep(ctx: WorkflowState, step: ProcessingStep) {
441→    // Mark step start in the logging system
442→    markStepStart(ctx.id, step as ProcessingPhase);
443→
444→    this.setState(ctx.id, {
445→      status: "processing",
446→      step,
447→      conversation: ctx.conversation,
448→      summary: ctx.summary,
449→      metadata: ctx.metadata,
450→      customPrompt: ctx.customPrompt,
451→      customSegmentationPrompt: ctx.customSegmentationPrompt,
452→      customSummaryPrompt: ctx.customSummaryPrompt,
453→      customAnalysisPrompt: ctx.customAnalysisPrompt,
454→      customColoringPrompt: ctx.customColoringPrompt,
455→      componentMapping: ctx.componentMapping,
456→      componentTimeline: ctx.componentTimeline,
457→      componentColors: ctx.componentColors,
458→      components: ctx.components,
459→      staticComponents: ctx.staticComponents,
460→      staticMapping: ctx.staticMapping,
461→      staticTimeline: ctx.staticTimeline,
462→      analysis: ctx.analysis,
463→      aiSummary: ctx.aiSummary,
464→      warnings:
465→        ctx.warnings && ctx.warnings.length > 0 ? ctx.warnings : undefined,
466→      stepTimings: ctx.stepTimings,
467→    });
468→  }
469→
470→  /**
471→   * Update state with current context (intermediate update, keeps status as 'success')
472→   */
473→  updateState(ctx: WorkflowState, nextStep?: ProcessingStep) {
474→    this.setState(ctx.id, {
475→      conversation: ctx.conversation,
476→      summary: ctx.summary,
477→      metadata: ctx.metadata,
478→      aiSummary: ctx.aiSummary,
479→      customPrompt: ctx.customPrompt,
480→      customSegmentationPrompt: ctx.customSegmentationPrompt,
481→      customSummaryPrompt: ctx.customSummaryPrompt,
482→      customAnalysisPrompt: ctx.customAnalysisPrompt,
483→      customColoringPrompt: ctx.customColoringPrompt,
