562→/**
563→ * Process conversation workflow: Single linear workflow with conditional step skipping
564→ */
565→async function processConversationWorkflow(
566→  event: WorkflowEvent,
567→  ctx: WorkflowState,
568→  runner: WorkflowRunner,
569→  callbacks: WorkflowCallbacks,
570→): Promise<void> {
571→  try {
572→    if (event === WorkflowEvent.SummaryPromptChanged) {
573→      ctx.aiSummary = "";
574→      runner.startStep(ctx, "summary");
575→      const { result: summaryResult, timing: summaryTiming } =
576→        await runner.runActivity(
577→          ctx,
578→          createSummaryActivity(callbacks.onSummaryChunk),
579→          "summary",
580→        );
581→      ctx.aiSummary = summaryResult.summary;
582→      if (summaryResult.error) ctx.warnings!.push(summaryResult.error);
583→      ctx.stepTimings!.summary = summaryTiming;
584→
585→      if (ctx.regenerateAnalysis) {
586→        ctx.analysis = "";
587→        runner.startStep(ctx, "analysis");
588→        const { result: analysisResult, timing: analysisTiming } =
589→          await runner.runActivity(
590→            ctx,
591→            createAnalysisActivity(callbacks.onAnalysisChunk),
592→            "analysis",
593→          );
594→        ctx.analysis = analysisResult.analysis;
595→        if (analysisResult.error) ctx.warnings!.push(analysisResult.error);
596→        ctx.stepTimings!.analysis = analysisTiming;
597→      }
598→
599→      runner.markComplete(ctx);
600→      return;
601→    }
602→
603→    // Resume from API key pause - continue from segmenting step
604→    if (event === WorkflowEvent.ResumeFromApiKeyPause) {
605→      // Step 3: Segment
606→      runner.startStep(ctx, "segmenting");
607→      const { result: segmentResult, timing: segmentTiming } =
608→        await runner.runActivity(ctx, segmentActivity, "segmenting");
609→
610→      ctx.conversation = segmentResult.conversation;
611→      if (segmentResult.error) ctx.warnings!.push(segmentResult.error);
612→      ctx.stepTimings!.segmenting = segmentTiming;
613→
614→      runner.updateState(ctx, "finding-components");
615→
616→      // Step 4: Find components
617→      runner.startStep(ctx, "finding-components");
618→      const { result: componentResult, timing: componentTiming } =
619→        await runner.runActivity(
620→          ctx,
621→          findComponentsActivity,
622→          "finding-components",
623→        );
624→      ctx.components = componentResult.components;
625→      ctx.componentMapping = componentResult.mapping;
626→      ctx.componentTimeline = componentResult.timeline;
627→      if (componentResult.error) ctx.warnings!.push(componentResult.error);
628→      ctx.stepTimings!["finding-components"] = componentTiming;
629→      runner.updateState(ctx, "coloring");
630→
631→      // Step 5: Assign colors
632→      runner.startStep(ctx, "coloring");
633→      const { result: colorResult, timing: colorTiming } =
634→        await runner.runActivity(ctx, assignColorsActivity, "coloring");
635→      ctx.componentColors = colorResult.colors;
636→      ctx.stepTimings!.coloring = colorTiming;
637→
638→      runner.markComplete(ctx);
639→      return;
640→    }
641→
642→    // Step 1: Parse (only for new files)
643→    if (event === WorkflowEvent.NewFile) {
644→      runner.startStep(ctx, "parsing");
645→      const { result, timing } = await runner.runActivity(
646→        ctx,
647→        parseActivity,
648→        "parsing",
649→      );

