  2→import { Slider } from "@/components/ui/slider";
  3→import { WaffleChart } from "./WaffleChart";
  4→import { CompactLegend } from "./ComponentComparisonView";
  5→import { cn } from "@/lib/utils";
  6→import { getComponentWaffleStyles } from "@/lib/component-colors";
  7→import { getStaticComponentLabel } from "@/lib/static-component-colors";
  8→import type { Conversation } from "@/schema";
  9→import type { ComponentTimelineSnapshot } from "@/componentisation";
 10→
 11→// Message type filter in format "role:type" (e.g., "assistant:tool-call")
 12→type MessageTypeFilter = string;
 13→
 14→interface ComponentsViewProps {
 15→  componentMapping?: Record<string, string>;
 16→  conversation: Conversation;
 17→  componentTimeline?: ComponentTimelineSnapshot[];
 18→  componentColors?: Record<string, string>;
 19→  selectedComponent?: string | null;
 20→  onComponentSelect?: (component: string | null) => void;
 21→  // Static component filter - when set, only show automatic components for parts matching this static component
 22→  staticMapping?: Record<string, string>;
 23→  filterByStaticComponent?: string | null;
 24→  // Filters from conversation view
 25→  messageTypeFilters?: Set<MessageTypeFilter>;
 26→}
 27→
 28→export function ComponentsView({
 29→  componentMapping,
 30→  conversation,
 31→  componentTimeline,
 32→  componentColors,
 33→  selectedComponent,
 34→  onComponentSelect,
 35→  staticMapping,
 36→  filterByStaticComponent,
 37→  messageTypeFilters,
 38→}: ComponentsViewProps) {
 39→  // Initialize slider to the last message
 40→  const [currentMessageIndex, setCurrentMessageIndex] = useState(
 41→    conversation.messages.length - 1
 42→  );
 43→
 44→  // Helper to check if a part passes the message type filter
 45→  const partPassesMessageTypeFilter = (part: { type: string }, msgRole: string): boolean => {
 46→    if (!messageTypeFilters || messageTypeFilters.has("all")) return true;
 47→    const filterKey = `${msgRole}:${part.type}`;
 48→    return messageTypeFilters.has(filterKey);
 49→  };
 50→
 51→  // Get the set of part IDs that match the static component filter
 52→  const filteredPartIds = useMemo(() => {
 53→    if (!filterByStaticComponent || !staticMapping) return null;
 54→
 55→    const ids = new Set<string>();
 56→    for (const [partId, staticComp] of Object.entries(staticMapping)) {
 57→      if (staticComp === filterByStaticComponent) {
 58→        ids.add(partId);
 59→      }
 60→    }
 61→    return ids;
 62→  }, [filterByStaticComponent, staticMapping]);
 63→
 64→  // Compute messageComponents for workflow view (filtered, up to current slider position)
 65→  // Must be before early return to follow React hooks rules
 66→  const messageComponents = useMemo(() => {
 67→    if (!componentMapping) return [];
 68→    const components: string[] = [];
 69→    conversation.messages.forEach((message, msgIndex) => {
 70→      if (msgIndex <= currentMessageIndex) {
 71→        // Find the primary component for this message from first matching part
 72→        let messageComponent: string | null = null;
 73→        for (const part of message.parts) {
 74→          // Apply message type filter
 75→          if (!partPassesMessageTypeFilter(part, message.role)) continue;
 76→
 77→          // Apply static component filter if set
 78→          if (filteredPartIds && !filteredPartIds.has(part.id)) continue;
 79→
 80→          const component = componentMapping[part.id];
 81→          if (component) {
 82→            messageComponent = component;
 83→            break;
 84→          }
 85→        }
 86→        // Only include message if it has parts that pass filters
 87→        if (messageComponent !== null) {
 88→          components.push(messageComponent);
 89→        }
 90→      }
 91→    });
 92→    return components;
 93→  }, [conversation.messages, currentMessageIndex, componentMapping, filteredPartIds, messageTypeFilters]);
 94→
 95→  if (!componentMapping || Object.keys(componentMapping).length === 0) {
 96→    return (
 97→      <div className="p-8 text-center text-muted-foreground">
 98→        <p>No component mapping available yet.</p>
 99→        <p className="text-sm mt-2">
100→          Component mapping will appear here after processing.

