194→/**
195→ * Map a batch of parts to components using AI
196→ */
197→async function mapPartsBatch(
198→  parts: PartWithContext[],
199→  components: string[],
200→  config: ComponentisationConfig,
201→  componentDescriptions?: string,
202→  conversationId?: string,
203→): Promise<Record<string, string>> {
204→  const openai = createOpenAI({
205→    apiKey: config.apiKey,
206→  });
207→
208→  // Create a simplified conversation structure for just these parts
209→  const partsJson = JSON.stringify(parts, null, 2);
210→  const componentsJson = JSON.stringify(components, null, 2);
211→
212→  const prompt = getPrompt("component-mapping", {
213→    conversationJson: partsJson,
214→    componentsJson,
215→    componentDescriptions: componentDescriptions || "",
216→  });
217→
218→  try {
219→    const result = await generateText({
220→      model: openai(config.model),
221→      prompt,
222→    });
223→
224→    // Parse the JSON response
225→    const jsonMatch = result.text.match(/\{[^]*\}/s);
226→    if (!jsonMatch) {
227→      log(conversationId, "No JSON object found in batch response");
228→      return {};
229→    }
230→
231→    const rawMapping = JSON.parse(jsonMatch[0]);
232→
233→    if (typeof rawMapping !== "object" || rawMapping === null) {
234→      log(conversationId, "Parsed batch result is not an object");
235→      return {};
236→    }
237→
238→    // Normalize component names - strip leading "- " that AI might add
239→    const mapping: Record<string, string> = {};
240→    for (const [key, value] of Object.entries(rawMapping)) {
241→      if (typeof value === "string") {
242→        mapping[key] = value.replace(/^-\s*/, "");
243→      }
244→    }
245→
246→    return mapping;
247→  } catch (error) {
248→    logError(conversationId, "Error calling AI for batch mapping", error);
249→    return {};
250→  }
251→}
252→
253→/**
254→ * Map message IDs to components using AI
255→ * Processes parts in batches of 20 in parallel for better coverage
256→ * Returns an object mapping message part IDs to component names
257→ */
258→export async function mapComponentsToIds(
259→  conversation: Conversation,
260→  components: string[],
261→  config: ComponentisationConfig,
262→  componentDescriptions?: string,
263→  conversationId?: string,
264→): Promise<Record<string, string>> {
265→  const BATCH_SIZE = 20;
266→
267→  // Strip binary data and extract parts with context
268→  const strippedConversation = stripLargeContent(conversation);
269→  const allParts = extractPartsWithContext(strippedConversation);
270→
271→  log(
272→    conversationId,
273→    `Mapping ${allParts.length} parts in batches of ${BATCH_SIZE} (model: ${config.model})`,
274→  );
275→
276→  // Split parts into batches
277→  const batches: PartWithContext[][] = [];
278→  for (let i = 0; i < allParts.length; i += BATCH_SIZE) {
279→    batches.push(allParts.slice(i, i + BATCH_SIZE));
280→  }
281→
282→  log(conversationId, `Processing ${batches.length} batches in parallel`);
283→
284→  // Process all batches in parallel
285→  const batchResults = await Promise.all(
286→    batches.map((batch, index) => {
287→      log(
288→        conversationId,
289→        `Starting batch ${index + 1}/${batches.length} (${batch.length} parts)`,
290→      );
291→      return mapPartsBatch(batch, components, config, componentDescriptions, conversationId);
292→    }),
293→  );
294→
295→  // Merge all batch results into a single mapping
296→  const mergedMapping: Record<string, string> = {};
297→  batchResults.forEach((batchMapping, index) => {
298→    const entriesCount = Object.keys(batchMapping).length;
299→    log(conversationId, `Batch ${index + 1} returned ${entriesCount} mappings`);
300→    Object.assign(mergedMapping, batchMapping);
301→  });
302→
303→  log(
304→    conversationId,
305→    `Created merged mapping with ${Object.keys(mergedMapping).length} entries (from ${allParts.length} parts)`,
306→  );
307→  return mergedMapping;
308→}
