310→/**
311→ * Timeline snapshot representing component composition at a specific message
312→ */
313→export interface ComponentTimelineSnapshot {
314→  messageIndex: number;
315→  componentTokens: Record<string, number>; // component name → total tokens
316→  totalTokens: number; // cumulative tokens up to this message
317→}
318→
319→/**
320→ * Build a timeline of component composition for each message in the conversation
321→ * This allows scrubbing through the conversation to see how components evolve
322→ */
323→export function buildComponentTimeline(
324→  conversation: Conversation,
325→  componentMapping: Record<string, string>,
326→  conversationId?: string,
327→): ComponentTimelineSnapshot[] {
328→  log(conversationId, "Building component timeline");
329→
330→  // Build a map of part ID to its message index and token count
331→  const partInfo = new Map<
332→    string,
333→    { messageIndex: number; tokenCount: number }
334→  >();
335→  conversation.messages.forEach((message, messageIndex) => {
336→    message.parts.forEach((part) => {
337→      const tokenCount = ("token_count" in part && part.token_count) || 0;
338→      partInfo.set(part.id, { messageIndex, tokenCount });
339→    });
340→  });
341→
342→  // Log mapping coverage for debugging
343→  const mappedCount = Object.keys(componentMapping).length;
344→  const totalParts = partInfo.size;
345→  log(
346→    conversationId,
347→    `Mapping coverage: ${mappedCount}/${totalParts} parts (${Math.round((mappedCount / totalParts) * 100)}%)`,
348→  );
349→
350→  // Build timeline snapshots
351→  const timeline: ComponentTimelineSnapshot[] = [];
352→
353→  for (let msgIndex = 0; msgIndex < conversation.messages.length; msgIndex++) {
354→    const componentTokens: Record<string, number> = {};
355→    let totalTokens = 0;
356→
357→    // Accumulate tokens for ALL parts up to and including this message
358→    // Use mapping if available, otherwise assign to "other"
359→    partInfo.forEach((info, partId) => {
360→      if (info.messageIndex <= msgIndex) {
361→        const component = componentMapping[partId] || "other";
362→        componentTokens[component] =
363→          (componentTokens[component] || 0) + info.tokenCount;
364→        totalTokens += info.tokenCount;
365→      }
366→    });
367→
368→    timeline.push({
369→      messageIndex: msgIndex,
370→      componentTokens,
371→      totalTokens,
372→    });
373→  }
374→
375→  log(conversationId, `Built timeline with ${timeline.length} snapshots`);
376→  return timeline;
377→}
