379→/**
380→ * Assign colors to components based on preset or AI
381→ * Returns an object mapping component names to color names
382→ */
383→export async function assignComponentColors(
384→  components: string[],
385→  config: ComponentisationConfig,
386→  conversationId?: string,
387→  presetColors?: Record<string, string>,
388→  customColoringPrompt?: string,
389→): Promise<Record<string, string>> {
390→  // If preset colors are provided, use them directly
391→  if (presetColors) {
392→    const colorMapping: Record<string, string> = {};
393→    for (const component of components) {
394→      colorMapping[component] = presetColors[component] || "gray";
395→    }
396→    logColoring(
397→      conversationId,
398→      `Using preset colors for ${Object.keys(colorMapping).length} components`,
399→    );
400→    return colorMapping;
401→  }
402→
403→  // AI-based color assignment
404→  const openai = createOpenAI({
405→    apiKey: config.apiKey,
406→  });
407→
408→  const componentsJson = JSON.stringify(components, null, 2);
409→
410→  console.log(
411→    `[Componentisation] Calling AI to assign colors (model: ${config.model})`,
412→  );
413→
414→  const prompt = getPrompt("component-coloring", { componentsJson, customPrompt: customColoringPrompt });
415→
416→  try {
417→    const result = await generateText({
418→      model: openai(config.model),
419→      prompt,
420→    });
421→
422→    console.log(`[Componentisation] AI response for colors: ${result.text}`);
423→
424→    // Parse the JSON response
425→    const jsonMatch = result.text.match(/\{[^]*\}/s);
426→    if (!jsonMatch) {
427→      console.log("[Componentisation] No JSON object found in response");
428→      return {};
429→    }
430→
431→    const rawColorMapping = JSON.parse(jsonMatch[0]);
432→
433→    if (typeof rawColorMapping !== "object" || rawColorMapping === null) {
434→      console.log("[Componentisation] Parsed result is not an object");
435→      return {};
436→    }
437→
438→    // Clean up keys - handle various AI response formats:
439→    // - Remove leading "- " that AI might add
440→    // - Extract component name from "name: description" format (some models include descriptions)
441→    const colorMapping: Record<string, string> = {};
442→    for (const [key, value] of Object.entries(rawColorMapping)) {
443→      let cleanKey = key.replace(/^-\s*/, "");
444→
445→      // If the key contains ": " followed by a description, extract just the component name
446→      // e.g., "identity: Establishes who the AI is..." -> "identity"
447→      // But preserve dots in component names like "personality.guidelines"
448→      const colonDescIndex = cleanKey.indexOf(": ");
449→      if (colonDescIndex > 0) {
450→        cleanKey = cleanKey.substring(0, colonDescIndex);
451→      }
452→
453→      if (typeof value === "string") {
454→        colorMapping[cleanKey] = value;
455→      }
456→    }
457→
458→    console.log(
459→      `[Componentisation] Assigned colors to ${Object.keys(colorMapping).length} components`,
460→    );
461→    return colorMapping;
462→  } catch (error) {
463→    console.error("[Componentisation] Error calling AI for colors:", error);
464→    return {};
465→  }
466→}
