128→/**
129→ * Lighten a hex color by mixing with white
130→ * @param hex The hex color to lighten
131→ * @param amount Amount to lighten (0-1, where 1 is white)
132→ */
133→export function lightenColor(hex: string, amount: number): string {
134→  const { r, g, b } = hexToRgb(hex);
135→  return rgbToHex(
136→    r + (255 - r) * amount,
137→    g + (255 - g) * amount,
138→    b + (255 - b) * amount
139→  );
140→}
141→
142→/**
143→ * Darken a hex color by mixing with black
144→ * @param hex The hex color to darken
145→ * @param amount Amount to darken (0-1, where 1 is black)
146→ */
147→export function darkenColor(hex: string, amount: number): string {
148→  const { r, g, b } = hexToRgb(hex);
149→  return rgbToHex(r * (1 - amount), g * (1 - amount), b * (1 - amount));
150→}
