186→/**
187→ * Mini waffle chart for comparison view - smaller 10x10 grid
188→ */
189→function MiniWaffleChart({
190→  componentTokens,
191→  totalTokens,
192→  componentColors,
193→  sortField,
194→  sortDirection,
195→}: {
196→  componentTokens: Record<string, number>;
197→  totalTokens: number;
198→  componentColors?: Record<string, string>;
199→  sortField: SortField;
200→  sortDirection: SortDirection;
201→}) {
202→  const GRID_SIZE = 100; // 10x10 grid for mini version
203→
204→  // Calculate percentages and sort based on field and direction
205→  const componentData = sortField === "category"
206→    ? sortByCategory(componentTokens, sortDirection)
207→    : Object.entries(componentTokens)
208→        .map(([component, tokens]) => ({
209→          component,
210→          tokens,
211→          percentage: totalTokens > 0 ? (tokens / totalTokens) * 100 : 0,
212→        }))
213→        .sort((a, b) => {
214→          const dir = sortDirection === "asc" ? 1 : -1;
215→          if (sortField === "name") {
216→            return a.component.localeCompare(b.component) * dir;
217→          }
218→          return (b.percentage - a.percentage) * dir;
219→        });
220→
221→  // Build the 100-square grid
222→  const squares: { component: string; index: number }[] = [];
223→  let squareIndex = 0;
224→
225→  for (const { component, percentage } of componentData) {
226→    const squareCount = Math.max(
227→      percentage > 0 ? 1 : 0,
228→      Math.round(percentage)
229→    );
230→
231→    for (let i = 0; i < squareCount && squareIndex < GRID_SIZE; i++) {
232→      squares.push({ component, index: squareIndex });
233→      squareIndex++;
234→    }
235→  }
236→
237→  while (squares.length < GRID_SIZE) {
238→    squares.push({ component: "", index: squares.length });
239→  }
240→  squares.length = GRID_SIZE;
241→
242→  return (
243→    <div className="flex-shrink-0 w-[138px] h-[138px]">
244→      <div className="grid grid-cols-[repeat(10,minmax(0,1fr))] gap-0.5">
245→        {squares.map(({ component, index }) => {
246→          const colorStyles = component ? getComponentWaffleStyles(component, componentColors) : null;
247→          return (
248→            <div
249→              key={index}
250→              className={cn(
251→                "w-3 h-3",
252→                component ? colorStyles?.classes : "bg-gray-200"
253→              )}
254→              style={colorStyles?.style || undefined}
255→              title={component || undefined}
256→            />
257→          );
258→        })}
259→      </div>
260→    </div>
261→  );
262→}
