264→/**
265→ * Format token count for labels (e.g., 1500 -> "1.5k", 250 -> "250")
266→ */
267→function formatTokenCount(tokens: number): string {
268→  if (tokens >= 1000) {
269→    const k = tokens / 1000;
270→    return k % 1 === 0 ? `${k}k` : `${k.toFixed(1)}k`;
271→  }
272→  return String(tokens);
273→}
