275→/**
276→ * Absolute waffle chart - each square = tokensPerSquare tokens
277→ * Height varies based on total tokens, enabling cross-conversation comparison
278→ */
279→function AbsoluteWaffleChart({
280→  componentTokens,
281→  totalTokens,
282→  componentColors,
283→  sortField,
284→  sortDirection,
285→  maxRows,
286→  tokensPerSquare,
287→  columns,
288→}: {
289→  componentTokens: Record<string, number>;
290→  totalTokens: number;
291→  componentColors?: Record<string, string>;
292→  sortField: SortField;
293→  sortDirection: SortDirection;
294→  maxRows: number;
295→  tokensPerSquare: number;
296→  columns: number;
297→}) {
298→  // Sort components
299→  const componentData = sortField === "category"
300→    ? sortByCategory(componentTokens, sortDirection)
301→    : Object.entries(componentTokens)
302→        .map(([component, tokens]) => ({
303→          component,
304→          tokens,
305→          percentage: totalTokens > 0 ? (tokens / totalTokens) * 100 : 0,
306→        }))
307→        .sort((a, b) => {
308→          const dir = sortDirection === "asc" ? 1 : -1;
309→          if (sortField === "name") {
310→            return a.component.localeCompare(b.component) * dir;
311→          }
312→          return (b.tokens - a.tokens) * dir;
313→        });
314→
315→  // Build squares array - fill with components
316→  const squares: { component: string }[] = [];
317→  for (const { component, tokens } of componentData) {
318→    const count = Math.max(tokens > 0 ? 1 : 0, Math.round(tokens / tokensPerSquare));
319→    for (let i = 0; i < count; i++) {
320→      squares.push({ component });
321→    }
322→  }
323→
324→  // Clamp and pad to exactly fill the grid (maxRows * columns)
325→  const totalCells = maxRows * columns;
326→  squares.length = Math.min(squares.length, totalCells);
327→  while (squares.length < totalCells) {
328→    squares.push({ component: "" });
329→  }
330→
331→  // Reverse so filled squares are at the bottom (CSS grid fills top-to-bottom)
332→  // We want the chart to grow upward from the baseline
333→  const reversed = [...squares].reverse();
334→
335→  return (
336→    <div className="flex flex-col items-center">
337→      <div className="text-xs text-muted-foreground mb-1 tabular-nums [font-variant:small-caps]">
338→        {formatTokenCount(totalTokens)}
339→      </div>
340→      <div
341→        className="grid gap-0.5"
342→        style={{
343→          gridTemplateColumns: `repeat(${columns}, 12px)`,
344→          gridTemplateRows: `repeat(${maxRows}, 12px)`,
345→        }}
346→      >
347→        {reversed.map((sq, index) => {
348→          const colorStyles = sq.component
349→            ? getComponentWaffleStyles(sq.component, componentColors)
350→            : null;
351→          return (
352→            <div
353→              key={index}
354→              className={cn(
355→                "w-3 h-3",
356→                sq.component ? colorStyles?.classes : "",
357→              )}
358→              style={colorStyles?.style || undefined}
359→              title={sq.component || undefined}
360→            />
361→          );
362→        })}
363→      </div>
364→    </div>
365→  );
366→}
