855→// ============================================================================
856→// Batch workflow orchestration
857→// ============================================================================
858→
859→interface WorkflowOptions {
860→  customComponents?: string[];
861→  presetColors?: Record<string, string>;
862→  customPrompt?: string;
863→  customSegmentationPrompt?: string;
864→}
865→
866→async function runWorkflows(
867→  files: File[],
868→  fileIds: Map<number, string>,
869→  onStepUpdate?: (id: string, step: ProcessingStep) => void,
870→  onFileComplete?: (conversation: WorkflowState) => void,
871→  onAISummaryChunk?: (id: string, chunk: string) => void,
872→  onAnalysisChunk?: (id: string, chunk: string) => void,
873→  options?: WorkflowOptions,
874→): Promise<WorkflowBatchResult> {
875→  // Give React a chance to render the placeholders before we start processing
876→  await new Promise((resolve) => setTimeout(resolve, 0));
877→
878→  // Process all files in parallel
879→  const workflowStates = await Promise.all(
880→    files.map(async (file, i) => {
881→      if (!file) return null;
882→
883→      const id = fileIds.get(i) || generateId();
884→
885→      // Create workflow runner for this file
886→      const runner = new WorkflowRunner((id, update) => {
887→        onFileComplete?.({
888→          id,
889→          filename: file.name,
890→          ...update,
891→        } as WorkflowState);
892→      });
893→
894→      // Initialize workflow context
895→      const ctx: WorkflowState = {
896→        id,
897→        filename: file.name,
898→        file,
899→        conversation: null as any, // Will be set by parse activity
900→        warnings: [],
901→        stepTimings: {},
902→        config: getComponentisationConfig(),
903→        customComponents: options?.customComponents,
904→        presetColors: options?.presetColors,
905→        customPrompt: options?.customPrompt,
906→        customSegmentationPrompt: options?.customSegmentationPrompt,
907→      };
908→
909→      // Run workflow with NewFile event
910→      await processConversationWorkflow(WorkflowEvent.NewFile, ctx, runner, {
911→        onSummaryChunk: onAISummaryChunk,
912→        onAnalysisChunk: onAnalysisChunk,
913→      });
914→
915→      // Return final parsed conversation
916→      return {
917→        id,
918→        filename: file.name,
919→        status: ctx.conversation ? "success" : "failed",
920→        conversation: ctx.conversation,
921→        summary: ctx.summary,
922→        metadata: ctx.metadata,
923→        aiSummary: ctx.aiSummary,
924→        components: ctx.components,
925→        componentMapping: ctx.componentMapping,
926→        componentTimeline: ctx.componentTimeline,
927→        componentColors: ctx.componentColors,
928→        staticComponents: ctx.staticComponents,
929→        staticMapping: ctx.staticMapping,
930→        staticTimeline: ctx.staticTimeline,
931→        analysis: ctx.analysis,
932→        warnings:
933→          ctx.warnings && ctx.warnings.length > 0 ? ctx.warnings : undefined,
934→        stepTimings: ctx.stepTimings,
935→      } as WorkflowState;
936→    }),
937→  );
938→
939→  // Filter out any null values from skipped files
940→  return {
941→    workflowStates: workflowStates.filter(
942→      (c): c is WorkflowState => c !== null,
943→    ),
944→  };
945→}
