 19→/**
 20→ * Waffle chart visualization showing token distribution as a 20x20 grid
 21→ * Each square represents 0.25% of total tokens
 22→ */
 23→export function WaffleChart({
 24→  componentTokens,
 25→  totalTokens,
 26→  getColorStyles,
 27→  getLabel,
 28→  onComponentClick,
 29→}: WaffleChartProps) {
 30→  const [sortMode, setSortMode] = useState<SortMode>("tokens");
 31→  const GRID_SIZE = 400; // 20x20 grid
 32→
 33→  // Calculate percentages and sort based on mode
 34→  const componentData = Object.entries(componentTokens)
 35→    .map(([component, tokens]) => ({
 36→      component,
 37→      tokens,
 38→      percentage: totalTokens > 0 ? (tokens / totalTokens) * 100 : 0,
 39→    }))
 40→    .sort((a, b) => {
 41→      if (sortMode === "name") {
 42→        return a.component.localeCompare(b.component);
 43→      }
 44→      return b.percentage - a.percentage;
 45→    });
 46→
 47→  // Build the 400-square grid (20x20)
 48→  // Each square is assigned to a component based on percentage
 49→  const squares: { component: string; index: number }[] = [];
 50→  let squareIndex = 0;
 51→
 52→  for (const { component, percentage } of componentData) {
 53→    // Calculate squares: percentage * 4 (since 400 squares = 100%)
 54→    // Ensure at least 1 square if component has tokens
 55→    const squareCount = Math.max(
 56→      percentage > 0 ? 1 : 0,
 57→      Math.round(percentage * 4)
 58→    );
 59→
 60→    for (let i = 0; i < squareCount && squareIndex < GRID_SIZE; i++) {
 61→      squares.push({ component, index: squareIndex });
 62→      squareIndex++;
 63→    }
 64→  }
 65→
 66→  // Fill remaining squares with empty (shouldn't happen if percentages add to 100)
 67→  while (squares.length < GRID_SIZE) {
 68→    squares.push({ component: "", index: squares.length });
 69→  }
 70→
 71→  // Trim to exactly 400
 72→  squares.length = GRID_SIZE;
 73→
 74→  return (
 75→    <div className="flex gap-8 items-start">
 76→      {/* Legend (left side) */}
 77→      <div className="flex flex-col gap-1.5 min-w-[240px]">
 78→        {/* Sort toggle */}
 79→        <div className="flex items-center gap-1 text-xs text-muted-foreground mb-1 px-2">
 80→          <span>Sort:</span>
 81→          <button
 82→            onClick={() => setSortMode("tokens")}
 83→            className={cn(
 84→              "px-1.5 py-0.5 rounded transition-colors",
 85→              sortMode === "tokens"
 86→                ? "bg-gray-200 text-gray-900"
 87→                : "hover:bg-gray-100"
 88→            )}
 89→          >
 90→            tokens
 91→          </button>
 92→          <button
 93→            onClick={() => setSortMode("name")}
 94→            className={cn(
 95→              "px-1.5 py-0.5 rounded transition-colors",
 96→              sortMode === "name"
 97→                ? "bg-gray-200 text-gray-900"
 98→                : "hover:bg-gray-100"
 99→            )}
100→          >
101→            name
102→          </button>
103→        </div>
104→        {componentData.map(({ component, tokens, percentage }) => {
105→          const colorStyles = getColorStyles(component);
106→          return (
107→            <button
108→              key={component}
109→              onClick={() => onComponentClick?.(component)}
110→              className={cn(
111→                "flex items-center gap-2 text-left text-sm py-1 px-2 rounded hover:bg-gray-100 transition-colors",
112→                onComponentClick && "cursor-pointer"
113→              )}
114→            >
115→              <span
116→                className={cn(
117→                  "w-4 h-4 flex-shrink-0",
118→                  colorStyles.classes
119→                )}
120→                style={colorStyles.style || undefined}
121→              />
122→              <span className="flex-1 truncate">{getLabel(component)}</span>
123→              <span className="text-muted-foreground tabular-nums text-xs w-16 text-right">
124→                {tokens.toLocaleString()}
125→              </span>
126→              <span className="text-muted-foreground tabular-nums w-10 text-right">
127→                {percentage.toFixed(0)}%
128→              </span>
129→            </button>
130→          );
131→        })}
132→      </div>
133→
134→      {/* Waffle grid (right side) - fixed 20x20 square */}
135→      <div className="grid grid-cols-[repeat(20,minmax(0,1fr))] gap-0.5 flex-shrink-0">
136→        {squares.map(({ component, index }) => {
137→          const colorStyles = component ? getColorStyles(component) : null;
138→          return (
139→            <button
140→              key={index}
141→              onClick={() => component && onComponentClick?.(component)}
142→              className={cn(
143→                "w-3 h-3 transition-all",
144→                component ? colorStyles?.classes : "bg-gray-200",
145→                component && onComponentClick && "cursor-pointer hover:scale-110"
146→              )}
147→              style={colorStyles?.style || undefined}
148→              title={component ? `${getLabel(component)}` : undefined}
149→            />
150→          );
151→        })}
152→      </div>
153→    </div>
154→  );
155→}
