// Map color names to waffle hex codes (the 400/500 level - more saturated)
export const colorNameToWaffleHex: Record<string, string> = {
  orange: "#fb923c",
  emerald: "#34d399",
  purple: "#c084fc",
  blue: "#60a5fa",
