  const [conversations, setConversations] = useState<WorkflowState[]>([]);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // URL state management
  const {
    state: urlState,
    navigateToConversation,
    navigateToTab,
    setInsightsTab,
    setSidebarCollapsed,
    setInsightsCollapsed,
    setSearchQuery,
    setSort,
    setMessageFilters,
    setComponentFilters,
