    } catch (error) {
      console.error("Failed to generate summary:", error);
      setConversations((prev) =>
        prev.map((c) =>
          c.id === id
            ? {
                ...c,
                status: "failed",
                step: undefined,
                error: "Summary generation failed",
              }
            : c,
        ),
      );
    } finally {
      setReprocessingId(null);
