 26→import { GroupFileOrderEditor } from "./GroupFileOrderEditor";
 27→import {
 28→  type ProcessingPhase,
 29→  type ConversationLogs,
 30→  type LogEntry,
 31→  type StepTiming,
 32→  getConversationLogs,
 33→  subscribeToLogs,
 34→  formatDuration,
 35→  formatTimestamp,
 36→} from "@/workflow-logger";
 37→
 38→type ProcessingStep =
 39→  | "parsing"
 40→  | "counting-tokens"
 41→  | "segmenting"
 42→  | "summary"
 43→  | "finding-components"
 44→  | "coloring"
 45→  | "analysis";
 46→
 47→interface StepInfo {
 48→  key: ProcessingStep;
 49→  label: string;
 50→  description: string;
 51→}
 52→
 53→const processingSteps: StepInfo[] = [
 54→  {
 55→    key: "parsing",
 56→    label: "Parse conversation",
 57→    description: "Parse the input file and extract conversation structure",
 58→  },
 59→  {
 60→    key: "counting-tokens",
 61→    label: "Count tokens",
 62→    description: "Count tokens for each message and part",
 63→  },
 64→  {
 65→    key: "segmenting",
 66→    label: "Segment content",
 67→    description: "Split large text parts into smaller segments using AI",
 68→  },
 69→  {
 70→    key: "summary",
 71→    label: "Generate summary",
 72→    description: "Generate an AI summary of the conversation",
 73→  },
 74→  {
 75→    key: "finding-components",
 76→    label: "Find components",
 77→    description: "Identify semantic components in the conversation using AI",
 78→  },
 79→  {
 80→    key: "coloring",
 81→    label: "Assign colors",
 82→    description: "Assign colors to identified components",
 83→  },
 84→  {
 85→    key: "analysis",
 86→    label: "Generate analysis",
 87→    description: "Generate detailed context analysis using AI",
 88→  },
 89→];
 90→
 91→interface WorkflowDetailModalProps {
 92→  isOpen: boolean;
 93→  onClose: () => void;
 94→  conversationId: string;
 95→  filename: string;
 96→  title?: string;
 97→  status?: "pending" | "processing" | "success" | "failed" | "paused-for-api-key";
 98→  currentStep?: ProcessingStep;
 99→  stepTimings?: Partial<Record<ProcessingStep, number>>;
100→  aiSummary?: string;
101→  warnings?: string[];
102→  onEditPrompt?: (id: string) => void;
103→  onEditComponents?: (id: string) => void;
104→  onEditSegmentationPrompt?: (id: string) => void;
105→  onEditSummaryPrompt?: (id: string) => void;
106→  onEditAnalysisPrompt?: (id: string) => void;
107→  onEditColoringPrompt?: (id: string) => void;
108→  onGenerateAnalysis?: (id: string) => void;
109→  onGenerateSummary?: (id: string) => void;
110→  // Grouped conversation support
111→  isGrouped?: boolean;
112→  sourceConversations?: Array<{ id: string; filename: string; title?: string }>;
113→  onUpdateGroupSources?: (newSources: Array<{ id: string; filename: string; title?: string }>) => void;
114→}
115→
116→export function WorkflowDetailModal({
117→  isOpen,
118→  onClose,
119→  conversationId,
120→  filename,
121→  title,
122→  status,
123→  currentStep,
124→  stepTimings,
125→  aiSummary,
126→  warnings,
127→  onEditPrompt,
128→  onEditComponents,
129→  onEditSegmentationPrompt,
130→  onEditSummaryPrompt,
131→  onEditAnalysisPrompt,
132→  onEditColoringPrompt,
133→  onGenerateAnalysis,
134→  onGenerateSummary,
135→  isGrouped,
136→  sourceConversations,
137→  onUpdateGroupSources,
138→}: WorkflowDetailModalProps) {
139→  const [logs, setLogs] = useState<ConversationLogs | null>(null);
140→  const [expandedSteps, setExpandedSteps] = useState<Set<ProcessingStep>>(
141→    new Set(),
142→  );
143→
144→  // Subscribe to log updates
145→  useEffect(() => {
146→    if (!conversationId) return;
147→
148→    // Get initial logs
149→    setLogs(getConversationLogs(conversationId));
150→
151→    // Subscribe to updates
152→    const unsubscribe = subscribeToLogs((id, newLogs) => {
153→      if (id === conversationId) {
154→        setLogs({ ...newLogs });
155→      }
156→    });
157→
158→    return unsubscribe;
159→  }, [conversationId]);
160→
161→  const toggleStep = (step: ProcessingStep) => {
162→    setExpandedSteps((prev) => {
163→      const next = new Set(prev);
164→      if (next.has(step)) {
165→        next.delete(step);
166→      } else {
167→        next.add(step);
168→      }
169→      return next;
170→    });
171→  };
172→
173→  const getStepStatus = (
174→    stepKey: ProcessingStep,
175→  ): "pending" | "in-progress" | "completed" | "not-run" => {
176→    if (status === "failed") return "pending";
177→    if (status === "pending") return "pending";
178→
179→    const stepIndex = processingSteps.findIndex((s) => s.key === stepKey);
180→    const currentStepIndex = processingSteps.findIndex(
181→      (s) => s.key === currentStep,
182→    );
183→
184→    // Special handling for summary step - check if aiSummary exists
185→    if (stepKey === "summary") {
186→      if (aiSummary && aiSummary.length > 0) {
187→        return "completed";
188→      }
189→      if (status === "processing" && currentStep === "summary") {
190→        return "in-progress";
191→      }
192→      return "pending";
193→    }
194→
195→    // If all steps completed (no current step and success)
196→    if (currentStepIndex === -1 && status === "success") {
197→      // Check if step was actually run (has timing or is before analysis)
198→      if (stepTimings?.[stepKey] !== undefined) {
199→        return "completed";
200→      }
201→      // Analysis is optional - if no timing, it wasn't run
202→      if (stepKey === "analysis") {
203→        return "not-run";
204→      }
205→      return "completed";
206→    }
207→
208→    if (stepIndex < currentStepIndex) return "completed";
209→    if (stepIndex === currentStepIndex) return "in-progress";
210→    return "pending";
211→  };
212→
213→  const getStepTiming = (stepKey: ProcessingStep): StepTiming | undefined => {
214→    return logs?.stepTimings[stepKey];
215→  };
216→
217→  const getLogsForStep = (stepKey: ProcessingStep): LogEntry[] => {
218→    if (!logs) return [];
219→    return logs.entries.filter((entry) => entry.phase === stepKey);
220→  };
221→
222→  const getStatusIcon = (
223→    stepStatus: "pending" | "in-progress" | "completed" | "not-run",
224→    stepKey: ProcessingStep,
225→  ) => {
226→    const isSummaryClickable =
227→      stepKey === "summary" &&
228→      status === "success" &&
229→      !currentStep &&
230→      stepTimings?.summary === undefined &&
231→      onGenerateSummary;
232→
233→    const isAnalysisClickable =
234→      stepKey === "analysis" &&
235→      status === "success" &&
236→      !currentStep &&
237→      stepTimings?.analysis === undefined &&
238→      onGenerateAnalysis;
239→
240→    if (isSummaryClickable || isAnalysisClickable) {
241→      return <Play className="h-4 w-4 text-blue-600" />;
242→    }
243→
244→    switch (stepStatus) {
245→      case "completed":
246→        return <Check className="h-4 w-4 text-green-600" />;
247→      case "in-progress":
248→        return <Loader2 className="h-4 w-4 animate-spin text-blue-600" />;
249→      case "not-run":
250→        return <Circle className="h-4 w-4 text-gray-300" />;
251→      default:
252→        return <Circle className="h-4 w-4 text-gray-300" />;
253→    }
254→  };
255→
256→  const formatTime = (date: Date): string => {
257→    return formatTimestamp(date);
258→  };
259→
260→  return (
261→    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
262→      <DialogContent className="max-w-3xl h-[85vh] flex flex-col overflow-hidden">
263→        <DialogHeader>
264→          <DialogTitle className="flex items-center gap-2">
265→            <span className="truncate">{title || filename}</span>
266→            {status === "processing" && (
267→              <Badge variant="secondary" className="shrink-0">
268→                <Loader2 className="h-3 w-3 animate-spin mr-1" />
269→                Processing
270→              </Badge>
271→            )}
272→            {status === "success" && !currentStep && (
273→              <Badge
274→                variant="secondary"
275→                className="shrink-0 bg-green-100 text-green-700"
276→              >
277→                <Check className="h-3 w-3 mr-1" />
278→                Complete
279→              </Badge>
280→            )}
281→            {status === "failed" && (
282→              <Badge variant="destructive" className="shrink-0">
283→                <AlertCircle className="h-3 w-3 mr-1" />
284→                Failed
285→              </Badge>
286→            )}
287→          </DialogTitle>
288→        </DialogHeader>
289→
290→        {warnings && warnings.length > 0 && (
291→          <div className="bg-yellow-50 border border-yellow-200 rounded-md p-3">
292→            <div className="flex items-center gap-2 text-yellow-700 text-sm font-medium mb-1">
293→              <AlertTriangle className="h-4 w-4" />
294→              Warnings ({warnings.length})
295→            </div>
296→            <ul className="text-xs text-yellow-600 space-y-1 ml-6">
297→              {warnings.map((warning, i) => (
298→                <li key={i}>{warning}</li>
299→              ))}
300→            </ul>
301→          </div>
302→        )}
303→
304→        <div className="flex-1 overflow-y-auto -mx-6 px-6">
305→          <div className="space-y-2 pb-4">
306→            {processingSteps.map((step) => {
307→              const stepStatus = getStepStatus(step.key);
308→              const timing = getStepTiming(step.key);
309→              const stepLogs = getLogsForStep(step.key);
310→              const isExpanded = expandedSteps.has(step.key);
311→              const legacyTiming = stepTimings?.[step.key];
312→
313→              const isSummaryClickable =
314→                step.key === "summary" &&
315→                status === "success" &&
316→                !currentStep &&
317→                stepTimings?.summary === undefined &&
318→                onGenerateSummary;
319→
320→              const isAnalysisClickable =
321→                step.key === "analysis" &&
322→                status === "success" &&
323→                !currentStep &&
324→                stepTimings?.analysis === undefined &&
325→                onGenerateAnalysis;
326→
327→              const isClickable = isSummaryClickable || isAnalysisClickable;
328→
329→              const isFindComponentsStep = step.key === "finding-components";
330→              const isSegmentingStep = step.key === "segmenting";
331→              const isSummaryStep = step.key === "summary";
332→              const isColoringStep = step.key === "coloring";
333→              const isAnalysisStep = step.key === "analysis";
334→
335→              return (
336→                <Collapsible
337→                  key={step.key}
338→                  open={isExpanded}
339→                  onOpenChange={() => toggleStep(step.key)}
340→                >
341→                  <div
342→                    className={cn(
343→                      "border rounded-lg",
344→                      stepStatus === "completed" &&
345→                        "border-green-200 bg-green-50/50",
346→                      stepStatus === "in-progress" &&
347→                        "border-blue-200 bg-blue-50/50",
348→                      stepStatus === "not-run" &&
349→                        "border-gray-200 bg-gray-50/50",
350→                      stepStatus === "pending" && "border-gray-200",
351→                    )}
352→                  >
353→                    <CollapsibleTrigger className="w-full">
354→                      <div className="flex items-center gap-3 p-3">
355→                        {getStatusIcon(stepStatus, step.key)}
356→                        <div className="flex-1 text-left">
357→                          <div className="flex items-center gap-2">
358→                            {isClickable ? (
359→                              <button
360→                                onClick={(e) => {
361→                                  e.stopPropagation();
362→                                  if (isSummaryClickable) {
363→                                    onGenerateSummary!(conversationId);
364→                                  } else {
365→                                    onGenerateAnalysis!(conversationId);
366→                                  }
367→                                }}
368→                                className="font-medium text-sm text-blue-600 hover:text-blue-700 hover:underline"
369→                              >
370→                                {step.label}
371→                              </button>
372→                            ) : (
373→                              <span
374→                                className={cn(
375→                                  "font-medium text-sm",
376→                                  stepStatus === "completed" &&
377→                                    "text-green-700",
378→                                  stepStatus === "in-progress" &&
